function load(){try{var r=localStorage.getItem(G2KEY);if(r){var d=JSON.parse(r);for(var k in d)if(d.hasOwnProperty(k))G[k]=d[k];}}catch(e){}G.ex=null;if(G.view==="parent")G.view="home";}
var saveT=null;
function save(){try{localStorage.setItem(G2KEY,JSON.stringify(G));}catch(e){}}
function saveSoon(){if(saveT)clearTimeout(saveT);saveT=setTimeout(save,400);}

// --- Праћење времена и активности (за родитеље) ---
function dkey(ms){var d=new Date(ms);return d.getFullYear()+"-"+("0"+(d.getMonth()+1)).slice(-2)+"-"+("0"+d.getDate()).slice(-2);}
var lastAct=0;
function act(){var n=Date.now();if(lastAct&&n-lastAct<120000&&!document.hidden){var k=dkey(n);G.time[k]=(G.time[k]||0)+(n-lastAct);saveSoon();}lastAct=n;}
["pointerdown","keydown","input"].forEach(function(ev2){document.addEventListener(ev2,act,true);});
document.addEventListener("scroll",act,{passive:true,capture:true});
document.addEventListener("visibilitychange",function(){if(document.hidden){lastAct=0;queueTime();save();flushReport();}});
function logIt(o){o.ts=Date.now();G.log.push(o);if(G.log.length>600)G.log=G.log.slice(-600);
 queueRow({ts:o.ts,vrsta:o.drill?"Брзо контирање":o.show?"Погледао рјешење":"Провјера",razred:o.g,zadatak:o.title||"",rezim:o.mode||"",pct:o.show?"":(o.drill?(o.ok?100:0):o.pct),napomena:o.drill?(o.ok?"тачно":"нетачно"):""});
 saveSoon();setTimeout(flushReport,1500);}

