 var dn=["Нед","Пон","Уто","Сри","Чет","Пет","Суб"];days.forEach(function(d){var dt=new Date(d[0]+"T12:00:00");s+='<div class="b"><small>'+(d[1]||"")+'</small><i style="height:'+Math.round(d[1]/max*80)+'%"></i><span>'+dn[dt.getDay()]+'</span></div>';});s+='</div></div>';
