document.addEventListener("change",function(e){var t=e.target;if(!t||!t.getAttribute||G.grade!==2)return;var k=t.getAttribute("data-g");if(k){I()[k]=t.value;saveSoon();return;}var dk=t.getAttribute("data-g2d");if(dk&&G.drill){G.drill[dk]=t.value;saveSoon();}});
document.addEventListener("focusout",function(e){var t=e.target;if(!t||!t.getAttribute||G.grade!==2)return;var k=t.getAttribute("data-g");if(k&&t.tagName==="INPUT"){var v=pv(t.value);if(t.value.trim()!==""&&v!==0){t.value=fmt(v);I()[k]=t.value;}}});
document.addEventListener("click",function(e){var b=e.target&&e.target.closest?e.target.closest("[data-g2a]"):null;if(!b)return;var a=b.getAttribute("data-g2a"),v=b.getAttribute("data-v");
 if(a==="grade"){G.grade=+v;G.view="home";save();window.scrollTo(0,0);render();return;}
 if(G.grade!==2)return;e.stopPropagation();
 if(a==="go"){G.view=v;G.ex=null;if(v!=="parent")parentOK=false;window.scrollTo(0,0);render();}
 else if(a==="open"){G.tid=v;G.view="task";G.tab="b";G.ex=null;S.showTT=true;window.scrollTo(0,0);render();}
 else if(a==="tab"){G.tab=v;G.ex=null;render();}
 else if(a==="mode"){S.learn=!S.learn;G.ex=null;render();}
 else if(a==="otv"){G.otv7000=v==="1";if(G.res[G.tid])delete G.res[G.tid];render();}
 else if(a==="ex"){G.ex=G.ex===v?null:v;render();}
 else if(a==="addrow"){var t=curT(),sol=solve(t),st=sol.st.filter(function(x){return x.nr===v;})[0];R()[v]=stavRows(st)+1;render();}
 else if(a==="delrow"){var r=+b.getAttribute("data-r"),s2=b.getAttribute("data-s"),t2=curT(),st2=solve(t2).st.filter(function(x){return x.nr===s2;})[0],n=stavRows(st2),im=I();
  for(var i=r;i<n-1;i++){["a","d","p"].forEach(function(c){im["j-"+s2+"-"+i+"-"+c]=im["j-"+s2+"-"+(i+1)+"-"+c]||"";});}
  ["a","d","p"].forEach(function(c){delete im["j-"+s2+"-"+(n-1)+"-"+c];});R()[s2]=Math.max(1,n-1);render();}
 else if(a==="check")doCheck2();else if(a==="show")doShow2();else if(a==="reset"){if(confirm("Обрисати све што је уписано у овом задатку?"))doReset2();}
 else if(a==="gen"){var nt=genTask(+v);if(G.gen){delete G.inp[G.gen.id];delete G.rows[G.gen.id];delete G.res[G.gen.id];}G.gen=nt;G.tid=nt.id;G.view="task";G.tab="b";G.ex=null;S.showTT=true;window.scrollTo(0,0);save();render();}
 else if(a==="qk"){G.quiz[v]=b.getAttribute("data-k");G.ex=null;save();render();}
 else if(a==="dchk"){var d=G.drill;if(!d.ad||!d.ap){alert("Изабери оба конта.");return;}d.done=true;var ok=d.ad===d.D&&d.ap===d.P;G.dst.n++;if(ok){G.dst.ok++;G.dst.streak++;if(G.dst.streak>G.dst.best)G.dst.best=G.dst.streak;}else G.dst.streak=0;logIt({g:2,title:"Брзо контирање",drill:true,ok:ok});save();render();}
 else if(a==="dnext"){newDrill();save();render();}
 else if(a==="pinset"){var p=(document.querySelector('[data-g2p="new"]')||{}).value||"";if(!/^\d{4}$/.test(p)){alert("PIN мора имати тачно 4 цифре.");return;}G.pin=p;parentOK=true;save();render();}
 else if(a==="pinok"){var p2=(document.querySelector('[data-g2p="try"]')||{}).value||"";if(p2===G.pin){parentOK=true;render();}else alert("Погрешан PIN.");}
 else if(a==="devsave"){G.devName=((document.querySelector('[data-g2p="dev"]')||{}).value||"").trim().slice(0,30);save();alert("Сачувано.");}
 else if(a==="pinlock"){parentOK=false;G.view="home";render();}
},true);

